class Solution {
    long getMaximumSumOfStrengths(int[] arr) {
        long prev2 = 0, prev1 = 0;
        for (int i = 1; i <= arr.length; i++) {
            long best = prev1 + (long) arr[i - 1] * i;
            if (i >= 2) best = Math.max(best, prev2 + (long) arr[i - 1] * (i - 1) + (long) arr[i - 2] * i);
            prev2 = prev1;
            prev1 = best;
        }
        return prev1;
    }
}

class Solution {
public:
    long long getMaximumSumOfStrengths(vector<int>& arr) {
        long long prev2 = 0, prev1 = 0;
        for (int i = 1; i <= (int)arr.size(); ++i) {
            long long best = prev1 + 1LL * arr[i - 1] * i;
            if (i >= 2) best = max(best, prev2 + 1LL * arr[i - 1] * (i - 1) + 1LL * arr[i - 2] * i);
            prev2 = prev1;
            prev1 = best;
        }
        return prev1;
    }
};
